files.agent-pane/theme.css:
/* Plush's chat: soft raised surfaces on one tinted page. Nothing here is glass and nothing has a
   border: every surface is the page's own color, set apart only by a pair of shadows, a light one
   up and to the left and a dark one down and to the right, so it seems pressed up out of the page
   (raised) or into it (a well). Your prompt box and your messages are raised; inline code and
   cards sit in shallow wells; the in-chat notice and the pickers are raised cards with 16 px
   corners. Links take the theme's one saturated accent, secondary text stays low-contrast.
   Every color is mixed from the theme's own (--agent-text, --agent-accent and --acpmux-base, the
   chat's opaque page), so this one file reads over Plush, Dusk and Clay in light and dark, and over
   any theme of your own. */
.acpmux-shell,
.ui-positioner {
  /* The two lights: the highlight a step toward white, the shade a step toward the ink and black. */
  --plush-hi: color-mix(in srgb, white 70%, var(--acpmux-base));
  --plush-lo: color-mix(in srgb, color-mix(in srgb, black 40%, var(--agent-text)) 24%, transparent);
  --plush-raise: -6px -6px 14px var(--plush-hi), 6px 6px 14px var(--plush-lo);
  --plush-raise-sm: -3px -3px 8px var(--plush-hi), 3px 3px 8px var(--plush-lo);
  --plush-well: inset 2px 2px 5px var(--plush-lo), inset -2px -2px 5px var(--plush-hi);

  --cv-card-fill: transparent;
  --cv-card-ring: transparent;
  --cv-code-bg: color-mix(in srgb, var(--agent-text) 6%, var(--acpmux-base));
  --cv-code-radius: 8px;
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 74%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 62%, transparent);
  /* Tool rows and "Worked for" draw --cv-activity-text (the stock 58% of the text). Plush's own ink is
     only 5.1:1 to 6.0:1 over its light pages, so the stock mix read 2.3:1 to 2.5:1 there: they take
     96% of the text in light (4.75:1 at worst, Plush) and 80% in dark (4.92:1 at worst, Plush Dark). */
  --cv-activity-text: color-mix(in srgb, var(--agent-text) 96%, transparent);
  --cv-link: var(--agent-accent);
  --agent-link: var(--agent-accent);

  /* The prompt box's own tokens: the page's fill, no edge and no rim. */
  --acpmux-composer-bg: var(--acpmux-base);
  --acpmux-composer-edge: transparent;
  --acpmux-composer-radius: 20px;
}
/* In the dark the highlight is only a lift of the page and the shade is deep. */
:root[data-theme="dark"] :is(.acpmux-shell, .ui-positioner) {
  --plush-hi: color-mix(in srgb, white 7%, var(--acpmux-base));
  --plush-lo: color-mix(in srgb, black 55%, transparent);
  --cv-activity-text: color-mix(in srgb, var(--agent-text) 80%, transparent);
}

/* The prompt box: raised out of the page, 20 px corners, no frost, ring or sheen. The repeated
   class outranks the box's own glass and ring rules whatever the sheet order. */
:root:root:root .acpmux-composer.acpmux-composer > .acpmux-composer-box {
  --glass-tint: var(--acpmux-base);
  --glass-backdrop: none;
  --glass-edge: transparent;
  --glass-rim: 0;
  --acpmux-card-ring: 0 0 0 0 transparent;
  --acpmux-composer-rim: 0 0 0 0 transparent;
  --acpmux-composer-shadow: var(--plush-raise);
  background: var(--acpmux-base) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: var(--plush-raise) !important;
  border-radius: 20px;
}
:root:root:root .acpmux-composer.acpmux-composer > .acpmux-composer-box::before {
  box-shadow: none !important;
}
/* The queued prompts over the box (its hat): one more raised card on the same page. */
:root:root:root .acpmux-composer.acpmux-composer > .acpmux-composer-queue {
  --glass-tint: var(--acpmux-base);
  --glass-backdrop: none;
  --glass-edge: transparent;
  background: var(--acpmux-base) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: var(--plush-raise-sm) !important;
}

/* Your messages: small raised cards in the page's color, 18 px corners, no glass. */
.acpmux-shell .cv-user__bubble {
  --glass-tint: var(--acpmux-base);
  --glass-opaque: var(--acpmux-base);
  --glass-backdrop: none;
  --glass-edge: transparent;
  --glass-rim: 0;
  background: var(--acpmux-base) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: var(--plush-raise-sm) !important;
  border-radius: 18px;
}

/* Inline code: a shallow well pressed into the page. */
.acpmux-shell .cv-code {
  box-shadow: var(--plush-well);
}

/* The in-chat notice (it was a frosted pill): a solid raised card with 16 px corners. */
.ui-notice.ui-glass {
  --glass-tint: var(--acpmux-base, Canvas);
  --glass-backdrop: none;
  --glass-edge: transparent;
  --glass-rim: 0;
  background: var(--acpmux-base, Canvas) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: var(--plush-raise-sm) !important;
  border-radius: 16px;
}

/* Pickers and menus over the chat: solid raised cards, 14 px corners, no frost. */
.ui-popup.ui-glass {
  --glass-tint: var(--acpmux-base, Canvas);
  --glass-backdrop: none;
  --glass-edge: transparent;
  --glass-rim: 0;
  background: var(--acpmux-base, Canvas) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: var(--plush-raise) !important;
  border-radius: 14px;
}

files.markdown/theme.css:
/* Plush's Markdown viewer: soft and borderless like the rest of the look. Code sits on a faint
   fill with round 14 px corners, headings carry no rule, quotes lean on a soft accent bar.
   Only --cmux-md-* custom properties on :root; every color is mixed from the page's own, so this
   one file reads over every Plush theme file, light and dark. */
:root {
  --cmux-md-code-background: color-mix(in srgb, var(--page-text) 6%, transparent);
  --cmux-md-code-radius: 14px;
  --cmux-md-heading-weight: 600;
  --cmux-md-heading-rule: none;
  --cmux-md-quote-border: 3px solid color-mix(in srgb, var(--cmux-accent, var(--page-text)) 45%, transparent);
}
